using System.Text;
using Mirror;
using MultiFPS;
using MultiFPS.UI;
using MultiFPS.Gameplay.RiftCombat;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.InputSystem;
namespace ROM.UI.Gameplay {
public sealed class RiftAbilityTooltip:MonoBehaviour {
 static RiftAbilityTooltip instance;GameObject owner;int ability=-1;string title,description,action;Canvas canvas;RectTransform panel,root;Text heading,body;float next;RectTransform inventoryBounds;bool compactInventory;Font defaultFont;
 public Font DisplayFont=>body?body.font:null;
 public string Heading=>heading?heading.text:"";
 public string Content=>body?body.text:"";public bool Visible=>panel&&panel.gameObject.activeSelf;
 public static RiftAbilityTooltip Current=>instance;
 static RiftAbilityTooltip Ensure(){if(!instance){var go=new GameObject("Rift ability tooltip",typeof(RectTransform));instance=go.AddComponent<RiftAbilityTooltip>();}return instance;}
 void Awake(){instance=this;canvas=gameObject.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=1000;root=(RectTransform)transform;var scaler=gameObject.AddComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);scaler.matchWidthOrHeight=1;var go=new GameObject("Ability tooltip",typeof(RectTransform),typeof(Image),typeof(Outline));go.transform.SetParent(transform,false);panel=(RectTransform)go.transform;panel.pivot=new Vector2(0,1);panel.sizeDelta=new Vector2(420,240);var frame=go.GetComponent<Image>();frame.color=new Color(.045f,.04f,.033f,.98f);frame.raycastTarget=false;go.GetComponent<Outline>().effectColor=new Color(.76f,.59f,.31f);go.GetComponent<Outline>().effectDistance=new Vector2(1,-1);var hud=FindFirstObjectByType<RiftGameplayHUD>();var font=hud&&hud.Theme&&hud.Theme.BodyFont?hud.Theme.BodyFont:Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");defaultFont=font;heading=Label("Ability name",16,12,388,32,24,font);heading.color=new Color(1,.81f,.43f);body=Label("Ability information",16,50,388,300,20,font);panel.gameObject.SetActive(false);}
 Text Label(string name,float x,float y,float w,float h,int size,Font font){var go=new GameObject(name,typeof(RectTransform),typeof(Text));go.transform.SetParent(panel,false);var rect=(RectTransform)go.transform;rect.anchorMin=rect.anchorMax=rect.pivot=new Vector2(0,1);rect.anchoredPosition=new Vector2(x,-y);rect.sizeDelta=new Vector2(w,h);var text=go.GetComponent<Text>();text.font=font;text.fontSize=size;text.color=new Color(.94f,.9f,.8f);text.raycastTarget=false;return text;}
 public static void ShowAbility(GameObject source,int id){var t=Ensure();t.owner=source;t.heading.font=t.body.font=t.defaultFont;t.compactInventory=false;t.inventoryBounds=null;t.ability=id;t.panel.gameObject.SetActive(true);t.next=0;t.Refresh();t.FitContent();}
 public static void ShowText(GameObject source,string name,string content,string key){var t=Ensure();t.owner=source;var scope=source.GetComponentInParent<ROM.UI.Sprint01.RiftInventoryFontScope>();t.compactInventory=scope;t.inventoryBounds=scope?(RectTransform)scope.transform:null;t.heading.font=t.body.font=scope&&scope.Font?scope.Font:t.defaultFont;t.ability=-1;t.title=name;t.description=content;t.action=key;t.panel.gameObject.SetActive(true);t.next=0;t.Refresh();t.FitContent();}
 public static void Hide(GameObject source){if(instance&&instance.owner==source)HideAll();}
 public static void HideAll(){if(instance){instance.owner=null;instance.panel.gameObject.SetActive(false);}}
 void OnDestroy(){if(instance==this)instance=null;}
 void Update(){if(!Visible)return;var parent=owner?owner.GetComponentInParent<Canvas>():null;if(!owner||!owner.activeInHierarchy||(parent&&!parent.enabled)||RiftHotbar.Dragging){HideAll();return;}if(Time.unscaledTime>=next){next=Time.unscaledTime+.1f;Refresh();}FitContent();if(Mouse.current!=null){RectTransformUtility.ScreenPointToLocalPointInRectangle(root,Mouse.current.position.ReadValue(),null,out var p);p+=new Vector2(18,panel.rect.height+24);if(compactInventory&&inventoryBounds){var corners=new Vector3[4];inventoryBounds.GetWorldCorners(corners);RectTransformUtility.ScreenPointToLocalPointInRectangle(root,RectTransformUtility.WorldToScreenPoint(null,corners[0]),null,out var left);p.x=left.x-panel.rect.width-14;var cell=owner.GetComponent<ROM.UI.Sprint01.RiftInventoryCell>();if(cell&&!cell.EquipmentTarget){var itemCorners=new Vector3[4];((RectTransform)owner.transform).GetWorldCorners(itemCorners);RectTransformUtility.ScreenPointToLocalPointInRectangle(root,RectTransformUtility.WorldToScreenPoint(null,itemCorners[1]),null,out var itemTop);p.x=itemTop.x-panel.rect.width-14;p.y=itemTop.y;}}p.x=Mathf.Clamp(p.x,root.rect.xMin+8,root.rect.xMax-panel.rect.width-8);p.y=Mathf.Clamp(p.y,root.rect.yMin+panel.rect.height+8,root.rect.yMax-8);panel.anchoredPosition=p;}}
 void FitContent(){if(!panel||!body)return;float width=compactInventory?320:420;body.fontSize=compactInventory?17:20;heading.fontSize=compactInventory?20:24;body.rectTransform.sizeDelta=new Vector2(width-32,body.rectTransform.sizeDelta.y);heading.rectTransform.sizeDelta=new Vector2(width-32,32);float h=Mathf.Clamp(body.preferredHeight,60,ability<0?440:340);body.rectTransform.sizeDelta=new Vector2(width-32,h);panel.sizeDelta=new Vector2(width,h+66);if(compactInventory){panel.GetComponent<Image>().color=new Color(.045f,.05f,.075f,.97f);panel.GetComponent<Outline>().effectColor=new Color(.5f,.44f,.65f,.6f);}}
 void Refresh(){var player=ClientFrontend.ClientPlayerInstance;var c=player?player.GetComponent<AbilityController>():null;if(ability<0){heading.text=title;body.text=description+(string.IsNullOrEmpty(action)?"":"\n\nAtajo: "+RiftControls.BindingLabel(action)+"\nReasignable en Controles.");return;}if(!c)return;var b=new StringBuilder();int slot=RiftHotbar.Slot(ability);if(ability==0){heading.text=c.AutoProfile.DisplayName;b.Append("Autoataque independiente\nDaño base: ").Append(c.AutoProfile.Damage).Append(" · Alcance: ").Append(c.AutoProfile.Range.ToString("0.0")).Append(" m\nCadencia: ").Append(c.AutoProfile.Interval.ToString("0.0")).Append(" s\nAtajo: ").Append(RiftControls.ActionLabel("AutoAttack"));}
 else if(c.Prototype){var a=c.Definition(ability);if(!a)return;heading.text=a.DisplayName;b.Append(string.IsNullOrWhiteSpace(a.Description)?a.Shape==AbilityShape.Arc?"Ataque frontal que alcanza a varios enemigos dentro de su arco.":a.Shape==AbilityShape.Circle?"Habilidad de área alrededor del personaje.":a.Shape==AbilityShape.Self?"Habilidad personal de protección o mejora.":"Habilidad dirigida hacia el objetivo.":a.Description).Append("\n\nDaño base: ").Append(a.Damage.ToString("0")).Append(" · Alcance/área: ").Append(c.AbilityRadius(ability,a).ToString("0.0")).Append(" m\nFuria: ").Append(a.Cost.ToString("0")).Append(" · Recarga: ").Append(c.AbilityCooldown(ability,a).ToString("0.0")).Append(" s\nEjecución: ").Append(a.CastDuration.ToString("0.0")).Append(" s");double remaining=c.Ready.Count>ability?System.Math.Max(0,c.Ready[ability]-NetworkTime.time):0;b.Append("\n").Append(!a.Implemented?"Todavía no disponible":!c.IsAbilityLearned(ability)?"No disponible en esta especialización":remaining>0?"Recargando: "+remaining.ToString("0.0")+" s":a.Cost>c.Resource?"Falta Furia":"Lista para usar");}
 else{var a=player.ClassDefinition;heading.text=ability==1?a.FirstAbility:ability==2?a.SecondAbility:"Espacio no disponible";b.Append(ability==1?a.FirstDescription:ability==2?a.SecondDescription:"Esta clase todavía no tiene una habilidad asignada aquí.");if(ability<=2)b.Append("\nRecarga: ").Append(ability==1?a.FirstCooldown:a.SecondCooldown).Append(" s");}
 if(ability>0&&slot>=0)b.Append("\nAtajo: ").Append(RiftControls.BindingLabel("Ability"+slot)).Append("\n\nArrastrá a otra ranura para intercambiar.\nEl orden se guarda por personaje y clase.");if(ability>0&&slot<0)b.Append("\nSin asignar a la barra. Asignala desde el libro de habilidades.");body.text=b.ToString();}
}}
